/* 27-calling-c/host.c — a C program that CALLS INTO Goose (exports.goose).
 *
 * From goose-guide:
 *   ../oss/goose/build/goose --standalone --header /tmp/exports.h \
 *       -o /tmp/exports.c 27-calling-c/exports.goose
 *   cc -I/tmp -o /tmp/host 27-calling-c/host.c /tmp/exports.c -lm && /tmp/host
 *
 * The generated C has no main() of its own: this file supplies it.
 */
#include <stdio.h>
#include "exports.h"   /* generated by --header: goose_init + the exported functions */

int main(int argc, char **argv) {
    /* 1. Call goose_init ONCE, before anything else: it sets up the runtime and
          the globals and runs the Goose `main` (if there is one). */
    goose_init(argc, argv);

    /* 2. A `const u8[:]` result: a pointer plus an int64_t* length out-param.
          The bytes are NOT NUL-terminated, so print with an explicit length. */
    int64_t len = 0;
    const uint8_t *msg = hello(&len);
    printf("[c] hello() -> \"%.*s\" (%lld bytes)\n", (int)len, (const char *)msg, (long long)len);

    /* 3. `export "c_add" fn add(...)` is callable as c_add. */
    printf("[c] c_add(20, 22) = %d\n", c_add(20, 22));
    printf("[c] c_add(1, 2)   = %d\n", c_add(1, 2));

    /* 4. Goose globals persist between calls (same thread as goose_init!). */
    printf("[c] call_count()  = %lld\n", (long long)call_count());
    return 0;
}
